import React, { useState } from 'react';
import { Link } from 'react-router-dom';

const DocumentUploadPage: React.FC = () => {
  const [pdfFile, setPdfFile] = useState<File | null>(null);
  const [extractedText, setExtractedText] = useState<string>('');
  const [isLoading, setIsLoading] = useState(false);
  const [showTextSection, setShowTextSection] = useState(false);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (file.type !== 'application/pdf') {
        alert('Please upload a PDF file');
        return;
      }
      setPdfFile(file);
      setExtractedText('');
      setShowTextSection(false);
    }
  };

  const handleExtractText = async () => {
    if (!pdfFile) {
      alert('Please upload a PDF file first');
      return;
    }

    try {
      setIsLoading(true);
      const formData = new FormData();
      formData.append('file', pdfFile);
      
      const response = await fetch('http://localhost:8000/api/pdf/upload', {
        method: 'POST',
        body: formData,
      });
      
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || 'Failed to extract text from PDF');
      }
      
      const data = await response.json();
      setExtractedText(data.text);
      setShowTextSection(true);
      console.log('Text extracted successfully:', data);
    } catch (error) {
      console.error('Error extracting text:', error);
      alert(`Error extracting text: ${error instanceof Error ? error.message : 'Unknown error'}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleGenerateSpeech = async () => {
    if (!extractedText) {
      alert('Please extract text from the PDF first');
      return;
    }

    const voicePath = localStorage.getItem('voicePath');
    if (!voicePath) {
      alert('No voice model found. Please record your voice first');
      return;
    }

    try {
      setIsLoading(true);
      const response = await fetch('http://localhost:8000/api/pdf/read', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          text: extractedText,
          voice_path: voicePath,
        }),
      });
      
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || 'Failed to generate speech');
      }
      
      const data = await response.json();
      console.log('Speech generated successfully:', data);
      
      // Create an audio element to play the generated speech
      const audioUrl = `http://localhost:8000${data.audio_path}`;
      const audio = new Audio(audioUrl);
      
      // Add error handling for audio loading
      audio.onerror = (e) => {
        console.error('Error loading audio:', e);
        alert('Error loading audio file. Please try again.');
      };

      // Add loading event to ensure audio is ready
      audio.oncanplaythrough = () => {
        audio.play().catch(error => {
          console.error('Error playing audio:', error);
          alert('Error playing audio. Please try again.');
        });
      };
    } catch (error) {
      console.error('Error generating speech:', error);
      alert(`Error generating speech: ${error instanceof Error ? error.message : 'Unknown error'}`);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100">
      <div className="max-w-4xl mx-auto py-12 px-4">
        <h1 className="text-4xl font-bold text-center mb-12">Document Upload</h1>
        
        <div className="bg-white rounded-lg shadow-sm p-8">
          <h2 className="text-2xl font-semibold mb-6">Upload PDF Document</h2>
          <div className="flex flex-col items-center">
            <button
              onClick={() => document.getElementById('pdf-upload')?.click()}
              className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors mb-4"
            >
              Choose File
            </button>
            <input
              id="pdf-upload"
              type="file"
              accept=".pdf"
              onChange={handleFileUpload}
              className="hidden"
            />
            {pdfFile && (
              <div className="text-gray-600 mt-2">
                Selected file: {pdfFile.name}
              </div>
            )}
          </div>
          {pdfFile && !showTextSection && (
            <div className="flex justify-center mt-6">
              <button
                onClick={handleExtractText}
                disabled={isLoading}
                className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors disabled:bg-blue-300"
              >
                {isLoading ? 'Extracting Text...' : 'Extract Text'}
              </button>
            </div>
          )}
        </div>

        {showTextSection && extractedText && (
          <div className="mt-8 bg-white rounded-lg shadow-sm p-8">
            <h2 className="text-2xl font-semibold mb-6">Extracted Text</h2>
            <div className="bg-gray-50 rounded-lg p-4 mb-6 max-h-60 overflow-y-auto">
              <p className="text-gray-700 whitespace-pre-wrap">{extractedText}</p>
            </div>
            <div className="flex justify-center">
              <button
                onClick={handleGenerateSpeech}
                disabled={isLoading}
                className="px-6 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors disabled:bg-green-300"
              >
                {isLoading ? 'Generating Speech...' : 'Generate Speech'}
              </button>
            </div>
          </div>
        )}

        <div className="mt-8 flex justify-center">
          <Link
            to="/"
            className="text-blue-600 hover:text-blue-800 font-medium"
          >
            ← Back to Voice Recording
          </Link>
        </div>
      </div>
    </div>
  );
};

export default DocumentUploadPage;
